/* IT CHICK Academy · Data Lab challenges: SQL (SQLite via sql.js) and R (base R via webR), both in the browser.
   SQL: the learner's query runs on a fresh database built from `setup`, and again on `setup2` (different numbers,
   to catch typed-in answers); its result must match the model answer's result on both. `ordered` = row order counts.
   R: the learner's code runs with `files`; each test is an R expression that must be TRUE afterwards (or `plot`,
   `src`, `srcNot`, `outHas`); with `files2` everything runs again on different data.
   also = other answers that must pass; traps = wrong answers that must fail with feedback containing `expect`
   (tools/check_datalab.py). All data is invented. */
window.DLAB_GROUPS = [
  {id:"sql", title:"SQL: ask a database questions", blurb:"SELECT, WHERE, ORDER BY, counting, GROUP BY, HAVING, JOIN and NULL, on a community garden’s database."},
  {id:"rbasics", title:"R: first steps", blurb:"Values, vectors and data frames in base R."},
  {id:"rdata", title:"R: working with a data file", blurb:"Read a CSV, pick rows, count, compare groups."},
  {id:"rstats", title:"R: charts, correlation and models", blurb:"A histogram, a correlation, a straight-line model and a simulation."}
];
(function(){
/* ---------- the garden database (two versions with different numbers) ---------- */
/* Version 2 is built to catch near-misses: a crop total of exactly 10 kg (> vs >=), harvests of exactly 3 kg,
   a repeated (crop, kg) pair (DISTINCT), a different set of crops over 10 kg, a different number of plots per bed,
   and a member with no harvests (inner vs outer JOIN). */
function garden(v){
  var H = v === 2 ? [
    [1,1,"beans",2.0,"2026-06"],[2,1,"tomatoes",6.0,"2026-07"],[3,2,"beans",3.0,"2026-06"],[4,3,"kale",2.5,"2026-05"],
    [5,3,"tomatoes",9.5,"2026-08"],[6,4,"beans",2.5,"2026-07"],[7,5,"squash",12.0,"2026-08"],[8,2,"kale",8.5,"2026-06"],
    [9,6,"tomatoes",7.5,"2026-07"],[10,4,"squash",3.0,"2026-09"],[11,5,"beans",2.5,"2026-06"]
  ] : [
    [1,1,"beans",2.5,"2026-06"],[2,1,"tomatoes",4.0,"2026-07"],[3,2,"beans",1.0,"2026-06"],[4,3,"kale",3.5,"2026-05"],
    [5,3,"tomatoes",8.0,"2026-08"],[6,4,"beans",3.0,"2026-07"],[7,5,"squash",10.5,"2026-08"],[8,2,"kale",1.5,"2026-06"],
    [9,6,"tomatoes",5.5,"2026-07"],[10,4,"squash",6.5,"2026-09"]
  ];
  var M = v === 2 ? [[1,"Ama",2021,1],[2,"Bilal",2024,2],[3,"Chen",2019,3],[4,"Dana",2023,null],[5,"Eitan",2020,4],[6,"Fatou",2025,null],[7,"Goran",2022,5]]
                  : [[1,"Ama",2021,1],[2,"Bilal",2024,2],[3,"Chen",2019,3],[4,"Dana",2023,4],[5,"Eitan",2020,null],[6,"Fatou",2025,5]];
  var P = v === 2 ? [[1,"North",6],[2,"North",4],[3,"South",8],[4,"South",5],[5,"East",10],[6,"North",7],[7,"East",3]]
                  : [[1,"North",6],[2,"North",4],[3,"South",8],[4,"South",5],[5,"East",10]];
  function q(x){ return x === null ? "NULL" : typeof x === "string" ? "'" + x + "'" : String(x); }
  return "CREATE TABLE members (id INTEGER PRIMARY KEY, name TEXT, joined INTEGER, plot_id INTEGER);\n" +
    "CREATE TABLE plots (id INTEGER PRIMARY KEY, bed TEXT, size_m2 REAL);\n" +
    "CREATE TABLE harvests (id INTEGER PRIMARY KEY, member_id INTEGER, crop TEXT, kg REAL, month TEXT);\n" +
    "INSERT INTO members VALUES " + M.map(function(r){ return "(" + r.map(q).join(",") + ")"; }).join(",") + ";\n" +
    "INSERT INTO plots VALUES " + P.map(function(r){ return "(" + r.map(q).join(",") + ")"; }).join(",") + ";\n" +
    "INSERT INTO harvests VALUES " + H.map(function(r){ return "(" + r.map(q).join(",") + ")"; }).join(",") + ";";
}
var G1 = garden(1), G2 = garden(2);
var TABLES = [
  ["members", "id, name, joined (the year they joined), plot_id (their plot, or NULL if they don’t have one yet)"],
  ["plots", "id, bed (North, South or East), size_m2"],
  ["harvests", "id, member_id, crop, kg, month (like '2026-06')"]
];
/* ---------- the survey file (two versions) ---------- */
var SURVEY1 = "id,group,age,hours,score,answer\n1,A,24,3,61,Yes\n2,A,31,5,70,Yes\n3,B,45,2,55,No\n4,B,29,6,78,Yes\n5,A,38,4,66,Unsure\n6,B,52,1,49,No\n7,A,27,7,83,Yes\n8,B,33,5,72,Unsure\n9,A,41,3,60,No\n10,B,36,8,88,Yes\n11,A,22,2,52,No\n12,B,30,6,75,Yes\n";
var SURVEY2 = "id,group,age,hours,score,answer\n1,A,19,2,50,No\n2,B,63,6,81,Yes\n3,A,28,4,64,Yes\n4,B,35,1,47,Unsure\n5,A,47,5,73,Yes\n6,B,26,3,58,Yes\n7,A,31,8,90,Yes\n8,B,40,2,53,No\n";
var F1 = {"survey.csv":SURVEY1}, F2 = {"survey.csv":SURVEY2};

window.DLAB = [
/* ============================ SQL ============================ */
{id:"dl-sql-select", group:"sql", kind:"sql", title:"SELECT two columns", lesson:"t3u9-l2",
 task:"Show the **crop** and **kg** of every harvest.", setup:G1, setup2:G2, tables:TABLES,
 start:"-- Write your query below\n", solution:"SELECT crop, kg FROM harvests;",
 also:["select crop, kg from harvests", "SELECT h.crop, h.kg FROM harvests AS h;", "SELECT crop, kg\nFROM harvests\nORDER BY kg;", "SELECT kg, crop FROM harvests", "-- crops and weights\nSELECT crop, kg FROM harvests -- every row", "/* q */ SELECT \"crop\", \"kg\" FROM harvests;", "SELECT crop AS Crop, kg AS weight FROM harvests;", "Select Crop, KG From Harvests"],
 traps:[{code:"SELECT * FROM harvests;", expect:"columns"},{code:"SELECT crop FROM harvests;", expect:"column"},{code:"SELECT crop, kg FROM harvest;", expect:"no table"},{code:"SELECT crop kg FROM harvests;", expect:"column"},{code:"SELECT crop, weight FROM harvests;", expect:"no column"},
   {code:"SELECT DISTINCT crop, kg FROM harvests;", expect:"DISTINCT removes repeated rows"},{code:"SELECT crop, kg FROM harvests LIMIT 5;", expect:"rows"},{code:"SELECT crop, kg, FROM harvests;", expect:"comma just before FROM"},{code:"SELECT crop, kg FORM harvests;", expect:"typo for FROM"},
   {code:"SELECT \u2018crop\u2019, kg FROM harvests;", expect:"curly quote"},{code:"SELECT 'crop', 'kg' FROM harvests;", expect:"Single quotes make text"},{code:"SELECT crop, kg FROM members;", expect:"no column"},{code:"", expect:"SELECT"}],
 hints:["SELECT lists the columns you want, separated by commas; FROM names the table.", "SELECT crop, kg FROM harvests;"],
 explain:"`SELECT` chooses columns and `FROM` chooses the table. SQL keywords aren’t case-sensitive (select works too), but writing them in capitals makes queries easier to read."},
{id:"dl-sql-where", group:"sql", kind:"sql", title:"WHERE: only the beans", lesson:"t3u9-l2",
 task:"Show **all columns** of the harvests where the crop is **beans**.", setup:G1, setup2:G2, tables:TABLES,
 start:"", solution:"SELECT * FROM harvests WHERE crop = 'beans';",
 also:["select * from harvests where crop='beans'", "SELECT * FROM harvests WHERE crop IN ('beans');", "SELECT id, member_id, crop, kg, month FROM harvests WHERE crop = 'beans';", "SELECT * FROM harvests h WHERE h.crop = 'beans' ORDER BY kg DESC;", "SELECT * FROM harvests WHERE 'beans' = crop", "SELECT * FROM harvests WHERE crop LIKE 'beans'"],
 traps:[{code:"SELECT * FROM harvests WHERE crop = beans;", expect:"single quotes"},{code:"SELECT * FROM harvests WHERE crop = 'Beans';", expect:"capitals count"},{code:"SELECT * FROM harvests;", expect:"rows"},{code:"SELECT * FROM harvests WHERE crop == \"tomatoes\";", expect:"values"},
   {code:"SELECT * FROM harvests WHERE id IN (1, 3, 6);", expect:"second"},{code:"SELECT * FROM harvests WHERE crop = 'beans' LIMIT 3;", expect:"second"},{code:"SELECT crop FROM harvests WHERE crop = 'beans';", expect:"column"},
   {code:"SELECT * FROM harvests WHERE crop = 'beans;", expect:"quote isn’t closed"},{code:"SELECT * FROM harvests WHERE crop = \u2018beans\u2019;", expect:"curly quote"},{code:"SELECT * FROM harvests WHERE crop != 'beans';", expect:"rows"}],
 hints:["WHERE keeps only the rows that match a condition.", "Text values go in single quotes: WHERE crop = 'beans'. Without quotes, SQLite looks for a column called beans."],
 explain:"`WHERE` filters rows. Text goes in 'single quotes'; without them SQLite thinks you mean a column. In SQLite, = compares text exactly, so 'Beans' and 'beans' are different values. (SQLite also accepts \"double quotes\" around text when no column has that name, but most databases read \"beans\" as a column name, so stick to single quotes.)"},
{id:"dl-sql-order", group:"sql", kind:"sql", title:"ORDER BY: newest members first", lesson:"t3u9-l2", ordered:true,
 task:"List members’ **name** and **joined** year, with the most recent joiners first.", setup:G1, setup2:G2, tables:TABLES,
 start:"", solution:"SELECT name, joined FROM members ORDER BY joined DESC;",
 also:["select name, joined from members order by joined desc, name", "SELECT joined, name FROM members ORDER BY joined DESC;", "SELECT name, joined FROM members ORDER BY 2 DESC", "SELECT name, joined AS year FROM members ORDER BY year DESC"],
 traps:[{code:"SELECT name, joined FROM members ORDER BY joined;", expect:"order"},{code:"SELECT name, joined FROM members;", expect:"order"},{code:"SELECT name, joined FROM members ORDER BY name DESC;", expect:"order"},
   {code:"SELECT name, joined FROM members ORDER BY joined DECS;", expect:"typo for DESC"},{code:"SELECT name FROM members ORDER BY joined DESC;", expect:"column"},{code:"SELECT name, joined FROM members ORDER BY joined DESC LIMIT 3;", expect:"rows"},{code:"SELECT name, joined FROM members ORDER BY 3 DESC;", expect:"ORDER BY with a number"}],
 hints:["ORDER BY sorts the result; add DESC for largest (or latest) first.", "ORDER BY joined DESC"],
 explain:"`ORDER BY` sorts; `ASC` (the default) is smallest first and `DESC` largest first. Without ORDER BY, a database may return rows in any order, so always sort when order matters."},
{id:"dl-sql-limit", group:"sql", kind:"sql", title:"The three biggest harvests", lesson:"t3u9-l2", ordered:true,
 task:"Show the **crop** and **kg** of the **three heaviest** harvests, heaviest first.", setup:G1, setup2:G2, tables:TABLES,
 start:"", solution:"SELECT crop, kg FROM harvests ORDER BY kg DESC LIMIT 3;",
 also:["select crop, kg from harvests order by kg desc limit 3", "SELECT kg, crop FROM harvests ORDER BY kg DESC LIMIT 3;", "SELECT crop, kg FROM harvests ORDER BY kg DESC, crop LIMIT 3 OFFSET 0"],
 traps:[{code:"SELECT crop, kg FROM harvests ORDER BY kg LIMIT 3;", expect:"Row 1"},{code:"SELECT crop, kg FROM harvests LIMIT 3;", expect:"Row"},{code:"SELECT crop, kg FROM harvests ORDER BY kg DESC;", expect:"rows"},
   {code:"SELECT crop, kg FROM harvests WHERE kg > 6 ORDER BY kg DESC;", expect:"second"},{code:"SELECT TOP 3 crop, kg FROM harvests ORDER BY kg DESC;", expect:"LIMIT"},{code:"SELECT crop, kg FROM harvests LIMIT 3 ORDER BY kg DESC;", expect:"LIMIT goes at the very end"},{code:"SELECT crop, MAX(kg) FROM harvests;", expect:"row"}],
 hints:["Sort first, then keep the top rows: ORDER BY … DESC LIMIT 3."],
 explain:"`LIMIT` keeps only the first rows of the result, so it only means “top 3” after `ORDER BY`. Without sorting, you get three rows in no guaranteed order."},
{id:"dl-sql-count", group:"sql", kind:"sql", title:"COUNT: how many big harvests?", lesson:"t3u9-l3",
 task:"How many harvests weighed **more than 3 kg**? Return one number.", setup:G1, setup2:G2, tables:TABLES,
 start:"", solution:"SELECT COUNT(*) FROM harvests WHERE kg > 3;",
 also:["select count(id) from harvests where kg > 3", "SELECT COUNT(*) AS big FROM harvests WHERE kg > 3.0;", "SELECT COUNT(kg) FROM harvests WHERE NOT kg <= 3", "SELECT SUM(kg > 3) FROM harvests"],
 traps:[{code:"SELECT COUNT(*) FROM harvests WHERE kg >= 3;", expect:">= also includes"},{code:"SELECT COUNT(*) FROM harvests;", expect:"right answer"},{code:"SELECT 6;", expect:"second"},{code:"SELECT * FROM harvests WHERE kg > 3;", expect:"column"},
   {code:"SELECT COUNT(*) FROM harvests WHERE kg > 3 GROUP BY crop;", expect:"rows"},{code:"SELECT COUNT(*) FROM harvests WHERE COUNT(kg) > 3;", expect:"HAVING"}],
 hints:["COUNT(*) counts rows. Put the condition in WHERE.", "“More than 3” is kg > 3 (3 itself doesn’t count)."],
 explain:"`COUNT(*)` counts the rows that are left after `WHERE`. The checker also ran your query on a second version of the database with different numbers, so typing the answer in won’t pass."},
{id:"dl-sql-groupby", group:"sql", kind:"sql", title:"GROUP BY: total per crop", lesson:"t3u9-l3",
 task:"Show each **crop** and its **total kg** across all harvests.", setup:G1, setup2:G2, tables:TABLES,
 start:"", solution:"SELECT crop, SUM(kg) FROM harvests GROUP BY crop;",
 also:["select crop, sum(kg) as total from harvests group by crop order by total desc", "SELECT crop, ROUND(SUM(kg), 1) FROM harvests GROUP BY crop;", "SELECT SUM(kg), crop FROM harvests GROUP BY crop", "SELECT crop, TOTAL(kg) FROM harvests GROUP BY 1", "select h.crop, sum(h.kg) total_kg from harvests h group by h.crop"],
 traps:[{code:"SELECT crop, SUM(kg) FROM harvests;", expect:"GROUP BY"},{code:"SELECT crop, AVG(kg) FROM harvests GROUP BY crop;", expect:"values"},{code:"SELECT crop, SUM(kg) FROM harvests GROUP BY kg;", expect:"rows"},{code:"SELECT crop, SUM(kg) FROM harvests GROUP crop;", expect:"order of the parts"},{code:"SELECT crop, kg FROM harvests GROUP BY crop;", expect:"values"},{code:"SELECT crop, COUNT(*) FROM harvests GROUP BY crop;", expect:"values"},{code:"SELECT SUM(kg) FROM harvests GROUP BY crop;", expect:"column"}],
 hints:["GROUP BY crop makes one group per crop; SUM(kg) adds up kg inside each group.", "SELECT crop, SUM(kg) FROM harvests GROUP BY crop;"],
 explain:"`GROUP BY` splits the rows into groups, and aggregate functions (`SUM`, `COUNT`, `AVG`, `MIN`, `MAX`) give one value per group. Every column in SELECT should either be in GROUP BY or inside an aggregate. (SQLite doesn’t insist on this: it quietly takes the value from one row of each group, which is rarely what you want.)"},
{id:"dl-sql-having", group:"sql", kind:"sql", title:"HAVING: crops over 10 kg", lesson:"t3u9-l3",
 task:"Show the **crop** and **total kg** for crops whose total is **more than 10 kg**.", setup:G1, setup2:G2, tables:TABLES,
 start:"", solution:"SELECT crop, SUM(kg) FROM harvests GROUP BY crop HAVING SUM(kg) > 10;",
 also:["select crop, sum(kg) as total from harvests group by crop having total > 10", "SELECT SUM(kg), crop FROM harvests GROUP BY crop HAVING SUM(kg) > 10 ORDER BY SUM(kg) DESC;", "SELECT * FROM (SELECT crop, SUM(kg) AS t FROM harvests GROUP BY crop) WHERE t > 10", "SELECT crop, ROUND(SUM(kg), 1) FROM harvests GROUP BY crop HAVING SUM(kg) > 10.0"],
 traps:[{code:"SELECT crop, SUM(kg) FROM harvests WHERE SUM(kg) > 10 GROUP BY crop;", expect:"HAVING"},{code:"SELECT crop, SUM(kg) FROM harvests WHERE kg > 10 GROUP BY crop;", expect:"row"},{code:"SELECT crop, SUM(kg) FROM harvests GROUP BY crop;", expect:"row"},
   {code:"SELECT crop, SUM(kg) FROM harvests GROUP BY crop HAVING SUM(kg) >= 10;", expect:"second"},{code:"SELECT crop, SUM(kg) FROM harvests WHERE crop IN ('tomatoes', 'squash') GROUP BY crop;", expect:"second"},{code:"SELECT crop, SUM(kg) FROM harvests GROUP BY crop HAVING SUM(kg) > 9;", expect:"second"},
   {code:"SELECT crop, SUM(kg) FROM harvests HAVING SUM(kg) > 10 GROUP BY crop;", expect:"HAVING goes after GROUP BY"},{code:"SELECT crop FROM harvests GROUP BY crop HAVING SUM(kg) > 10;", expect:"column"}],
 hints:["WHERE filters rows before grouping; HAVING filters groups after.", "… GROUP BY crop HAVING SUM(kg) > 10"],
 explain:"`WHERE` runs before grouping, so it can’t see totals. `HAVING` runs after `GROUP BY`, so it can filter on `SUM`, `COUNT` and friends. SQLite also lets HAVING use a name given in SELECT (`HAVING total > 10`), but many other databases don’t, so repeating `SUM(kg)` is the safer habit."},
{id:"dl-sql-join", group:"sql", kind:"sql", title:"JOIN: who grew what", lesson:"t3u9-l4",
 task:"Show each harvest with the **member’s name**, the **crop** and the **kg**. (Member names are in `members`; harvests store `member_id`.)", setup:G1, setup2:G2, tables:TABLES,
 start:"", solution:"SELECT members.name, harvests.crop, harvests.kg FROM harvests JOIN members ON harvests.member_id = members.id;",
 also:["select m.name, h.crop, h.kg from harvests h inner join members m on m.id = h.member_id", "SELECT name, crop, kg FROM members JOIN harvests ON members.id = harvests.member_id;", "SELECT kg, crop, name FROM harvests JOIN members ON members.id = harvests.member_id ORDER BY name", "SELECT m.name, h.crop, h.kg FROM harvests AS h, members AS m WHERE h.member_id = m.id", "SELECT m.name, h.crop, h.kg FROM harvests h LEFT JOIN members m ON h.member_id = m.id"],
 traps:[{code:"SELECT name, crop, kg FROM members, harvests;", expect:"rows"},{code:"SELECT m.name, h.crop, h.kg FROM members m LEFT JOIN harvests h ON h.member_id = m.id;", expect:"outer JOIN"},{code:"SELECT member_id, crop, kg FROM harvests;", expect:"values"},{code:"SELECT name, crop, kg FROM harvests NATURAL JOIN members;", expect:"rows"},{code:"SELECT members.name, harvests.crop, harvests.kg FROM harvests JOIN members ON harvests.id = members.id;", expect:"row"},{code:"SELECT name, crop, kg FROM harvests JOIN members ON member_id = id;", expect:"ambiguous"}],
 hints:["JOIN puts two tables side by side; ON says which rows belong together.", "… FROM harvests JOIN members ON harvests.member_id = members.id"],
 explain:"A `JOIN` matches rows using a key: here `harvests.member_id` points at `members.id` (a **foreign key** pointing at a **primary key**). Without `ON`, every row is paired with every other row, which is almost never what you want."},
{id:"dl-sql-null", group:"sql", kind:"sql", title:"NULL: members without a plot", lesson:"t3u9-l3",
 task:"Show the **names** of members who don’t have a plot yet (their `plot_id` is empty, which SQL calls NULL).", setup:G1, setup2:G2, tables:TABLES,
 start:"", solution:"SELECT name FROM members WHERE plot_id IS NULL;",
 also:["select name from members where plot_id is null order by name", "SELECT m.name FROM members m WHERE m.plot_id IS NULL;", "SELECT name FROM members WHERE NOT plot_id IS NOT NULL"],
 traps:[{code:"SELECT name FROM members WHERE plot_id = NULL;", expect:"IS NULL"},{code:"SELECT name FROM members WHERE name = 'Eitan';", expect:"second"},{code:"SELECT * FROM members WHERE plot_id IS NULL;", expect:"columns"},{code:"SELECT name FROM members WHERE plot_id = 'NULL';", expect:"IS NULL"},{code:"SELECT name FROM members WHERE plot_id = 0;", expect:"rows"},{code:"SELECT name FROM members WHERE plot_id IS NOT NULL;", expect:"rows"}],
 hints:["NULL means “no value”, and nothing is equal to NULL, not even NULL. Use IS NULL."],
 explain:"`NULL` isn’t a value, it’s the absence of one, so `plot_id = NULL` is never true. Use `IS NULL` and `IS NOT NULL`. Aggregates like `COUNT(plot_id)` also skip NULLs, which is a common surprise."},
{id:"dl-sql-fix", group:"sql", kind:"sql", title:"Fix the query", lesson:"t3u9-l3",
 task:"This query should list each **bed** and its **number of plots**, only for beds with **2 or more plots**. Run it, read the error, and fix it.", setup:G1, setup2:G2, tables:TABLES,
 start:"SELECT bed, COUNT(*)\nFROM plots\nWHERE COUNT(*) >= 2\nGROUP BY bed;", solution:"SELECT bed, COUNT(*)\nFROM plots\nGROUP BY bed\nHAVING COUNT(*) >= 2;",
 also:["select bed, count(id) as n from plots group by bed having n >= 2", "SELECT COUNT(*), bed FROM plots GROUP BY bed HAVING COUNT(*) > 1 ORDER BY bed;"],
 traps:[{code:"SELECT bed, COUNT(*) FROM plots GROUP BY bed HAVING COUNT(*) = 2;", expect:"second"},{code:"SELECT bed, COUNT(*) FROM plots WHERE bed != 'East' GROUP BY bed;", expect:"second"},{code:"SELECT bed, COUNT(*) FROM plots GROUP BY bed WHERE COUNT(*) >= 2;", expect:"WHERE has to come before GROUP BY"},{code:"SELECT bed, COUNT(*) FROM plots GROUP BY bed HAVING COUNT(*) > 2;", expect:"no rows"},{code:"SELECT bed, COUNT(*)\nFROM plots\nWHERE COUNT(*) >= 2\nGROUP BY bed;", expect:"HAVING"},{code:"SELECT bed, COUNT(*) FROM plots GROUP BY bed;", expect:"rows"}],
 hints:["COUNT can’t be used in WHERE. Which clause filters groups?", "Move the condition after GROUP BY, as HAVING COUNT(*) >= 2."],
 explain:"Error messages point at the problem: “misuse of aggregate” means an aggregate is in the wrong place. Filters on totals go in `HAVING`."},

/* ============================ R basics ============================ */
{id:"dl-r-calc", group:"rbasics", kind:"r", title:"Store and calculate", lesson:"t3u7-l2",
 task:"A ticket costs 12.5 and you buy 4. Store the price in `price`, the number in `qty`, and their product in `total`. Then print `total`.",
 start:"# Use <- to store a value\n", solution:"price <- 12.5\nqty <- 4\ntotal <- price * qty\ntotal",
 also:["price = 12.5; qty = 4; total = price * qty; print(total)", "price <- 12.5\nqty <- 4L\ntotal <- qty * price\ncat(total)", "12.5 -> price\n4 -> qty\n(total <- price * qty)", "price <- 12.5 # in pounds\nqty <- 4\ntotal <- price * qty\nprint(total)\nstr(total)"],
 tests:[{t:"price is 12.5 and qty is 4", r:"exists('price') && exists('qty') && .same(price, 12.5) && .same(qty, 4)", msg:"Store price <- 12.5 and qty <- 4 (numbers, with a full stop for the decimal)."},
        {t:"total is price × qty", r:"exists('total') && exists('price') && exists('qty') && .same(total, price * qty)", msg:"total should be price * qty (* multiplies)."},
        {t:"total is worked out from the other two", srcNot:"total\\s*(<-|=)\\s*50\\b", msg:"Calculate total from price and qty (price * qty) rather than typing 50."},
        {t:"total is printed", outHas:"50", msg:"Print total: type total on a line of its own (or use print(total))."}],
 traps:[{code:"total <- 50\ntotal", expect:"price"},{code:"price <- 12.5\nqty <- 4\ntotal <- price + qty\ntotal", expect:"total is price"},{code:"price <- 12.5\nqty <- 4\ntotal <- price * qty", expect:"printed"},{code:"price <- 12,5\nqty <- 4", expect:"comma"},
   {code:"price <- \"12.5\"\nqty <- 4\ntotal <- price * qty\ntotal", expect:"maths with text"},{code:"price <- 12.5\nqty <- 4\ntotal <- price * qty\nTotal", expect:"did you mean “total”"},{code:"price <- 12.5\nqty <- 4\ntotal <- 50\ntotal", expect:"rather than typing 50"},{code:"price <- 12.5 qty <- 4", expect:"nothing between them"}],
 hints:["In R, `<-` stores a value: price <- 12.5. Decimals use a full stop.", "Typing a name on its own line prints it."],
 explain:"`<-` (or `=`) stores a value under a name. Typing a name on its own prints it, which is how R shows results. R uses a full stop for decimals whatever your computer’s language settings."},
{id:"dl-r-vector", group:"rbasics", kind:"r", title:"A vector of scores", lesson:"t3u7-l2",
 task:"Using the vector `scores`, store the mean in `avg` and the median in `mid`, and the number of scores in `n`.",
 start:"scores <- c(72, 88, 95, 60, 81, 67)\n", solution:"scores <- c(72, 88, 95, 60, 81, 67)\navg <- mean(scores)\nmid <- median(scores)\nn <- length(scores)",
 also:["scores <- c(72, 88, 95, 60, 81, 67)\navg <- sum(scores) / length(scores)\nmid <- median(scores)\nn <- length(scores)\navg; mid; n", "scores = c(72, 88, 95, 60, 81, 67)\navg = mean(scores)\nmid = median(scores)\nn = length(scores)\nsummary(scores)", "scores <- c(72, 88, 95, 60, 81, 67)\navg <- mean(x = scores)\nmid <- quantile(scores, 0.5)\nn <- NROW(scores)", "scores <- c(72, 88, 95, 60, 81, 67)\navg <- scores |> mean()\nmid <- scores |> median()\nn <- scores |> length()\nprint(c(avg, mid, n))"],
 tests:[{t:"avg is the mean", r:"exists('avg') && .same(avg, mean(c(72, 88, 95, 60, 81, 67)))", msg:"avg should be mean(scores)."},
        {t:"mid is the median", r:"exists('mid') && .same(mid, median(c(72, 88, 95, 60, 81, 67)))", msg:"mid should be median(scores): the middle value, not the mean."},
        {t:"n is the number of scores", r:"exists('n') && .same(n, 6)", msg:"n should be length(scores). (nrow() is for data frames: on a vector it gives NULL.)"},
        {t:"worked out from scores", srcNot:"77\\.1|\\b76\\.5\\b|\\bn\\s*(<-|=)\\s*6\\b", msg:"Use mean(), median() and length() on scores rather than typing the answers."}],
 traps:[{code:"scores <- c(72, 88, 95, 60, 81, 67)\navg <- mean(scores)\nmid <- mean(scores)\nn <- length(scores)", expect:"median"},{code:"scores <- c(72, 88, 95, 60, 81, 67)\navg <- Mean(scores)", expect:"did you mean “mean”"},{code:"scores <- c(72, 88, 95, 60, 81, 67)\navg <- mean(Scores)", expect:"did you mean “scores”"},
   {code:"scores <- c(72, 88, 95, 60, 81, 67)\navg <- mean(scores)\nmid <- median(scores)\nn <- nrow(scores)", expect:"length(scores)"},{code:"scores <- c(72, 88, 95, 60, 81, 67)\navg <- 77.17\nmid <- 76.5\nn <- 6", expect:"mean(scores)"},{code:"scores <- c(72, 88, 95, 60, 81, 67)\navg <- mean(scores)\nmid <- median(scores)\nn <- 6", expect:"rather than typing"}],
 hints:["mean(), median() and length() each take the whole vector.", "With an even number of values, the median is halfway between the two middle ones: R does that for you."],
 explain:"`c()` combines values into a **vector**, R’s basic building block. Most R functions work on a whole vector at once, so there’s no loop needed."},
{id:"dl-r-df", group:"rbasics", kind:"r", title:"Make a data frame", lesson:"t3u7-l3",
 task:"Make a data frame `cafes` with two columns: `name` (\"Bean There\", \"Cup Up\", \"Steep\") and `price` (3.2, 2.8, 3.5). Then store the mean price in `avg_price`.",
 start:"", solution:"cafes <- data.frame(\n  name = c(\"Bean There\", \"Cup Up\", \"Steep\"),\n  price = c(3.2, 2.8, 3.5)\n)\navg_price <- mean(cafes$price)",
 also:["cafes <- data.frame(name = c('Bean There', 'Cup Up', 'Steep'), price = c(3.2, 2.8, 3.5))\navg_price <- mean(cafes[[\"price\"]])\ncafes", "cafes <- data.frame(name = c(\"Bean There\", \"Cup Up\", \"Steep\"), price = c(3.2, 2.8, 3.5), stringsAsFactors = TRUE)\navg_price <- mean(cafes[, \"price\"])\nstr(cafes)", "name <- c(\"Bean There\", \"Cup Up\", \"Steep\")\nprice <- c(3.2, 2.8, 3.5)\ncafes <- data.frame(name, price)\navg_price <- mean(price)"],
 tests:[{t:"cafes is a data frame with 3 rows", r:"exists('cafes') && is.data.frame(cafes) && nrow(cafes) == 3", msg:"Make cafes with data.frame(name = c(…), price = c(…)), three values in each column."},
        {t:"it has the columns name and price", r:"exists('cafes') && is.data.frame(cafes) && all(c('name', 'price') %in% names(cafes))", msg:"The columns should be called name and price (lower case)."},
        {t:"the names are right", r:"exists('cafes') && is.data.frame(cafes) && identical(as.character(cafes$name), c('Bean There', 'Cup Up', 'Steep'))", msg:"name should be \"Bean There\", \"Cup Up\" and \"Steep\", in that order (capitals and spaces count)."},
        {t:"the prices are right", r:"exists('cafes') && is.data.frame(cafes) && is.numeric(cafes$price) && .same(cafes$price, c(3.2, 2.8, 3.5))", msg:"price should be 3.2, 2.8 and 3.5, in that order, as numbers (no quotes)."},
        {t:"avg_price is the mean of the price column", r:"exists('avg_price') && is.numeric(avg_price) && !is.na(avg_price) && .same(avg_price, mean(c(3.2, 2.8, 3.5)))", msg:"avg_price should be mean(cafes$price)."}],
 traps:[{code:"cafes <- data.frame(name = c(\"Bean There\", \"Cup Up\", \"Steep\"), price = c(\"3.2\", \"2.8\", \"3.5\"))\navg_price <- mean(cafes$price)", expect:"numbers"},{code:"cafes <- data.frame(name = c(\"Bean There\", \"Cup Up\"), price = c(3.2, 2.8, 3.5))", expect:"different lengths"},{code:"cafes <- data.frame(name = c(\"Bean There\", \"Cup Up\", \"Steep\"), price = c(3.2, 2.8, 3.5))\navg_price <- mean(price)", expect:"cafes$price"},
   {code:"cafes <- data.frame(name = c(\"Bean there\", \"Cup up\", \"Steep\"), price = c(3.2, 2.8, 3.5))\navg_price <- mean(cafes$price)", expect:"capitals"},{code:"cafes <- data.frame(name = c(\"Bean There\", \"Cup Up\", \"Steep\"), price = c(3.2, 2.8, 3.5))\navg_price <- mean(Cafes$price)", expect:"did you mean “cafes”"},{code:"cafes <- c(name = \"Bean There\", price = 3.2)\navg_price <- 3.17", expect:"data.frame("}],
 hints:["data.frame(name = c(…), price = c(…)) makes a table with one column per argument.", "cafes$price picks out the price column."],
 explain:"A **data frame** is R’s table: each column is a vector, and every column has the same length. `$` picks a column by name."},

/* ============================ R with a data file ============================ */
{id:"dl-r-csv", group:"rdata", kind:"r", title:"Read a CSV", lesson:"t3u7-l4", files:F1, files2:F2,
 task:"Read `survey.csv` into a data frame called `d`. Store the number of rows in `n_people` and the mean age in `avg_age`.",
 start:"", solution:"d <- read.csv(\"survey.csv\")\nn_people <- nrow(d)\navg_age <- mean(d$age)",
 also:["d <- read.csv('survey.csv')\nstr(d)\nn_people <- dim(d)[1]\navg_age <- mean(d[[\"age\"]])", "d <- read.csv(\"survey.csv\")\nn_people <- nrow(d)\navg_age <- colMeans(d[\"age\"])", "d <- read.csv(file = \"survey.csv\", header = TRUE)\nhead(d)\nn_people <- nrow(d)\navg_age <- mean(d$age)\nprint(avg_age)", "d <- read.table(\"survey.csv\", header = TRUE, sep = \",\")\nn_people <- length(d$id)\navg_age <- sum(d$age) / nrow(d)\nsummary(d)"],
 tests:[{t:"d holds the file", r:"exists('d') && is.data.frame(d) && identical(names(d), names(read.csv('survey.csv')))", msg:"Read the file with d <- read.csv(\"survey.csv\")."},
        {t:"n_people is the number of rows", r:"exists('n_people') && .same(n_people, nrow(read.csv('survey.csv')))", msg:"n_people should be nrow(d): the number of rows, one per person."},
        {t:"avg_age is the mean age", r:"exists('avg_age') && .same(avg_age, mean(read.csv('survey.csv')$age))", msg:"avg_age should be mean(d$age)."}],
 traps:[{code:"d <- read.csv(\"Survey.csv\")", expect:"couldn’t find that file"},{code:"d <- read.csv(\"survey.csv\")\nn_people <- 12\navg_age <- 34", expect:"second version"},{code:"d <- read.csv(\"survey.csv\")\nn_people <- length(d)\navg_age <- mean(d$age)", expect:"rows"},
   {code:"d <- read.csv(survey.csv)", expect:"File names go in quotes"},{code:"d <- read.csv(\"survey.csv\")\nn_people <- nrow(d)\navg_age <- mean(d$Age)", expect:"misspelt column"},{code:"d <- read_csv(\"survey.csv\")", expect:"base R"},{code:"library(readr)\nd <- read_csv(\"survey.csv\")", expect:"can’t be installed"}],
 hints:["read.csv(\"survey.csv\") reads the file; nrow() counts rows.", "length() of a data frame gives the number of columns, not rows."],
 explain:"`read.csv()` turns a CSV file into a data frame. `str(d)` and `head(d)` are the first things to run on new data: they show the columns and their types. The checker also ran your code on a second version of the file, so typed-in numbers won’t pass."},
{id:"dl-r-subset", group:"rdata", kind:"r", title:"Pick rows", lesson:"t3u7-l4", files:F1, files2:F2,
 task:"From `survey.csv`, make `older`: only the people aged **30 or over**. Store how many there are in `n_older`.",
 start:"d <- read.csv(\"survey.csv\")\n", solution:"d <- read.csv(\"survey.csv\")\nolder <- d[d$age >= 30, ]\nn_older <- nrow(older)",
 also:["d <- read.csv(\"survey.csv\")\nolder <- subset(d, age >= 30)\nn_older <- nrow(older)", "d <- read.csv(\"survey.csv\")\nolder <- d |> subset(age >= 30)\nn_older <- sum(d$age >= 30)", "d <- read.csv(\"survey.csv\")\nolder <- d[which(d$age >= 30), ]\nn_older <- nrow(older)\nolder", "d = read.csv(\"survey.csv\")\nolder = d[!(d$age < 30), ]\nn_older = length(older$age)\nhead(older)"],
 tests:[{t:"older has only people aged 30+", r:"exists('older') && is.data.frame(older) && all(older$age >= 30) && nrow(older) == sum(read.csv('survey.csv')$age >= 30) && ncol(older) == ncol(read.csv('survey.csv'))", msg:"older should be the rows of d where age is 30 or more, with all the columns: d[d$age >= 30, ]. (30 itself counts, so use >=.)"},
        {t:"n_older is how many", r:"exists('n_older') && .same(n_older, sum(read.csv('survey.csv')$age >= 30))", msg:"n_older should be nrow(older)."}],
 traps:[{code:"d <- read.csv(\"survey.csv\")\nolder <- d[d$age > 30, ]\nn_older <- nrow(older)", expect:"30+"},{code:"d <- read.csv(\"survey.csv\")\nolder <- d[d$age >= 30]\nn_older <- nrow(older)", expect:"comma"},{code:"d <- read.csv(\"survey.csv\")\nolder <- d[age >= 30, ]", expect:"d$age"},
   {code:"d <- read.csv(\"survey.csv\")\nolder <- d[d$age >= 30, \"age\"]\nn_older <- length(older)", expect:"all the columns"},{code:"d <- read.csv(\"survey.csv\")\nolder <- d[d$age >= 30, ]\nn_older <- length(older)", expect:"nrow(older)"},{code:"d <- read.csv(\"survey.csv\")\nolder <- filter(d, age >= 30)", expect:"subset(d, age >= 30)"},{code:"d <- read.csv(\"survey.csv\")\nolder <- d[d$age => 30, ]", expect:">="}],
 hints:["d[rows, columns]: put a TRUE/FALSE condition before the comma and leave the columns part empty.", "d[d$age >= 30, ] — note the comma."],
 explain:"`d[condition, ]` keeps the rows where the condition is TRUE. `subset(d, age >= 30)` does the same and reads more easily. A handy trick: `sum(condition)` counts the TRUEs."},
{id:"dl-r-table", group:"rdata", kind:"r", title:"Count answers", lesson:"t3u7-l4", files:F1, files2:F2,
 task:"Count how many people gave each `answer` (Yes, No, Unsure) and store the counts in `counts`. Then store the **share** (proportion) of Yes answers in `share_yes`.",
 start:"d <- read.csv(\"survey.csv\")\n", solution:"d <- read.csv(\"survey.csv\")\ncounts <- table(d$answer)\nshare_yes <- mean(d$answer == \"Yes\")",
 also:["d <- read.csv(\"survey.csv\")\ncounts <- table(d$answer)\nshare_yes <- counts[[\"Yes\"]] / sum(counts)", "d <- read.csv(\"survey.csv\")\ncounts <- table(d$answer)\nshare_yes <- as.numeric(prop.table(counts)[\"Yes\"])", "d <- read.csv(\"survey.csv\")\ncounts <- summary(factor(d$answer))\nshare_yes <- sum(d$answer == \"Yes\") / nrow(d)\ncounts", "d <- read.csv(\"survey.csv\")\ncounts <- table(d$answer)\nshare_yes <- prop.table(counts)[[\"Yes\"]]\nprop.table(counts)", "d <- read.csv(\"survey.csv\")\ncounts <- as.data.frame(table(d$answer))\nshare_yes <- mean(d$answer == \"Yes\")"],
 tests:[{t:"counts holds the count of each answer", r:"exists('counts') && { s <- table(read.csv('survey.csv')$answer); v <- if (is.data.frame(counts)) setNames(counts[[ncol(counts)]], as.character(counts[[1]])) else counts; !is.null(names(v)) && setequal(names(v), names(s)) && .same(as.numeric(v[names(s)]), as.numeric(s)) }", msg:"counts should be table(d$answer): one count for each answer."},
        {t:"share_yes is the proportion of Yes", r:"exists('share_yes') && length(share_yes) == 1 && .same(share_yes, mean(read.csv('survey.csv')$answer == 'Yes'))", msg:"share_yes should be one number, the proportion between 0 and 1 (Yes count ÷ number of people), for example mean(d$answer == \"Yes\")."}],
 traps:[{code:"d <- read.csv(\"survey.csv\")\ncounts <- table(d$answer)\nshare_yes <- counts[[\"Yes\"]]", expect:"proportion"},{code:"d <- read.csv(\"survey.csv\")\ncounts <- table(d$group)\nshare_yes <- mean(d$answer == \"Yes\")", expect:"each answer"},{code:"d <- read.csv(\"survey.csv\")\ncounts <- table(d$answer)\nshare_yes <- mean(d$answer == \"yes\")", expect:"proportion"},
   {code:"d <- read.csv(\"survey.csv\")\ncounts <- table(d$answer)\nshare_yes <- 100 * mean(d$answer == \"Yes\")", expect:"between 0 and 1"},{code:"d <- read.csv(\"survey.csv\")\ncounts <- table(d$answer)\nshare_yes <- 0.5", expect:"second version"},{code:"d <- read.csv(\"survey.csv\")\ncounts <- table(d$answer)\nshare_yes <- prop.table(counts)", expect:"one number"}],
 hints:["table(d$answer) counts each value.", "d$answer == \"Yes\" gives TRUE/FALSE; mean() of TRUE/FALSE is the share of TRUEs."],
 explain:"`table()` makes a frequency table. Because TRUE counts as 1 and FALSE as 0, `mean(condition)` is the proportion of rows where the condition holds: a very handy R idiom. Text comparisons are case-sensitive: \"yes\" isn’t \"Yes\"."},
{id:"dl-r-groups", group:"rdata", kind:"r", title:"Compare groups", lesson:"t3u7-l5", files:F1, files2:F2,
 task:"Store the **mean score for each group** (A and B) in `by_group`, using `tapply()` or `aggregate()`.",
 start:"d <- read.csv(\"survey.csv\")\n", solution:"d <- read.csv(\"survey.csv\")\nby_group <- tapply(d$score, d$group, mean)",
 also:["d <- read.csv(\"survey.csv\")\nby_group <- aggregate(score ~ group, data = d, FUN = mean)", "d <- read.csv(\"survey.csv\")\nby_group <- c(A = mean(d$score[d$group == \"A\"]), B = mean(d$score[d$group == \"B\"]))", "d <- read.csv(\"survey.csv\")\nby_group <- aggregate(d$score, by = list(group = d$group), FUN = mean)\nby_group", "d <- read.csv(\"survey.csv\")\nby_group <- sapply(split(d$score, d$group), mean)", "d <- read.csv(\"survey.csv\")\nby_group <- with(d, tapply(score, group, mean))\nround(by_group, 1)", "d <- read.csv(\"survey.csv\")\nby_group <- aggregate(cbind(score, hours) ~ group, data = d, FUN = mean)"],
 tests:[{t:"by_group has the mean score of A and of B", r:"exists('by_group') && { s <- read.csv('survey.csv'); w <- tapply(s$score, s$group, mean); v <- if (is.data.frame(by_group)) setNames(by_group[[if ('score' %in% names(by_group)) 'score' else ncol(by_group)]], as.character(by_group[[1]])) else by_group; .same(as.numeric(v[c('A','B')]), as.numeric(w[c('A','B')])) }", msg:"by_group should hold two means, one for A and one for B: tapply(d$score, d$group, mean). Values first, then the groups, then the function."}],
 traps:[{code:"d <- read.csv(\"survey.csv\")\nby_group <- tapply(d$score, d$group, median)", expect:"mean score"},{code:"d <- read.csv(\"survey.csv\")\nby_group <- mean(d$score)", expect:"mean score"},{code:"d <- read.csv(\"survey.csv\")\nby_group <- tapply(d$group, d$score, mean)", expect:"Values first"},
   {code:"d <- read.csv(\"survey.csv\")\nby_group <- tapply(d$score, d$Group, mean)", expect:"misspelt column"},{code:"d <- read.csv(\"survey.csv\")\nby_group <- tapply(d$score, d$answer, mean)", expect:"one for A"},{code:"d <- read.csv(\"survey.csv\")\nby_group <- d %>% group_by(group) %>% summarise(m = mean(score))", expect:"|>"}],
 hints:["tapply(values, groups, function) applies the function to the values in each group.", "tapply(d$score, d$group, mean)"],
 explain:"`tapply()` splits a column by a grouping column and applies a function to each piece; `aggregate()` does the same and returns a data frame. Comparing group means is the start of many analyses, but remember the spread too."},

/* ============================ R stats and charts ============================ */
{id:"dl-r-hist", group:"rstats", kind:"r", title:"A histogram", lesson:"t3u7-l5", files:F1,
 task:"Draw a **histogram** of `hours` from `survey.csv`, with the title \"Hours of study\" and the x-axis label \"Hours per week\".",
 start:"d <- read.csv(\"survey.csv\")\n", solution:"d <- read.csv(\"survey.csv\")\nhist(d$hours, main = \"Hours of study\", xlab = \"Hours per week\")",
 also:["d <- read.csv(\"survey.csv\")\nhist(d$hours, xlab = \"Hours per week\", main = \"Hours of study\", col = \"grey\")", "d <- read.csv(\"survey.csv\")\nhist(d[[\"hours\"]], main = 'Hours of study', xlab = 'Hours per week')", "d <- read.csv(\"survey.csv\")\nwith(d, hist(hours, main = \"Hours of study\", xlab = \"Hours per week\"))", "d <- read.csv(\"survey.csv\")\nd$hours |> hist(main = \"Hours of study\", xlab = \"Hours per week\", breaks = 8)", "d <- read.csv(\"survey.csv\")\nh <- d$hours\nhist(x = h, main = \"Hours of study\", xlab = \"Hours per week\", col = \"steelblue\", border = \"white\")\nsummary(h)"],
 tests:[{t:"a chart was drawn", plot:true},
        {t:"it’s a histogram of hours", r:"length(.hist_of(read.csv('survey.csv')$hours)) > 0", msg:"Draw it with hist() and the hours column: hist(d$hours, …)."},
        {t:"the title is set", r:"any(vapply(.hist_of(read.csv('survey.csv')$hours), function(h) identical(as.character(h$main), 'Hours of study'), TRUE))", msg:"Add main = \"Hours of study\" inside hist( ), exactly as written (capitals count)."},
        {t:"the x-axis label is set", r:"any(vapply(.hist_of(read.csv('survey.csv')$hours), function(h) identical(as.character(h$xlab), 'Hours per week'), TRUE))", msg:"Add xlab = \"Hours per week\" inside hist( ), exactly as written."}],
 traps:[{code:"d <- read.csv(\"survey.csv\")\nbarplot(d$hours)", expect:"hist"},{code:"d <- read.csv(\"survey.csv\")\nhist(d$hours)", expect:"main"},{code:"d <- read.csv(\"survey.csv\")\nhist(d$hours, main = \"Hours of study\")", expect:"xlab"},
   {code:"d <- read.csv(\"survey.csv\")\nhist(d$score, main = \"Hours of study\", xlab = \"Hours per week\")", expect:"hours column"},{code:"d <- read.csv(\"survey.csv\")\nhist(d$hours, main = \"hours of study\", xlab = \"Hours per week\")", expect:"capitals"},{code:"d <- read.csv(\"survey.csv\")\nhist(d)", expect:"one numeric column"},{code:"d <- read.csv(\"survey.csv\")\nplot(d$hours, main = \"Hours of study\", xlab = \"Hours per week\")", expect:"hist"},{code:"d <- read.csv(\"survey.csv\")\nhist(d$hours, title = \"Hours of study\", xlab = \"Hours per week\")", expect:"isn’t an argument"},{code:"d <- read.csv(\"survey.csv\")\nhist(d$hours, xlab = \"Hours of study\", main = \"Hours per week\")", expect:"main = \"Hours of study\""}],
 hints:["hist() draws a histogram of one numeric column.", "main = sets the title, xlab = the x-axis label."],
 explain:"A histogram shows the **shape** of a distribution: where values cluster, how spread out they are, and whether there’s a long tail. Always label axes with units."},
{id:"dl-r-cor", group:"rstats", kind:"r", title:"Correlation", lesson:"t3u7-l5", files:F1, files2:F2,
 task:"Store the correlation between `hours` and `score` in `r_hs` (Pearson’s r, R’s default).",
 start:"d <- read.csv(\"survey.csv\")\n", solution:"d <- read.csv(\"survey.csv\")\nr_hs <- cor(d$hours, d$score)",
 also:["d <- read.csv(\"survey.csv\")\nr_hs <- cor(d$score, d$hours)\nround(r_hs, 2)", "d <- read.csv(\"survey.csv\")\nr_hs <- cor(d$hours, d$score, method = \"pearson\")", "d <- read.csv(\"survey.csv\")\nr_hs <- with(d, cor(hours, score))\nplot(d$hours, d$score)", "d <- read.csv(\"survey.csv\")\nr_hs <- cor(d[, c(\"hours\", \"score\")])[1, 2]", "d <- read.csv(\"survey.csv\")\nr_hs <- cor.test(d$hours, d$score)$estimate"],
 tests:[{t:"r_hs is Pearson’s r for hours and score", r:"exists('r_hs') && length(r_hs) == 1 && { s <- read.csv('survey.csv'); .same(r_hs, cor(s$hours, s$score)) }", msg:"r_hs should be one number, Pearson’s r for hours and score: cor(d$hours, d$score). Keep the full value (round only when you print)."}],
 traps:[{code:"d <- read.csv(\"survey.csv\")\nr_hs <- cor(d$hours, d$age)", expect:"hours and score"},{code:"d <- read.csv(\"survey.csv\")\nr_hs <- round(cor(d$hours, d$score), 1)", expect:"round only when you print"},
   {code:"d <- read.csv(\"survey.csv\")\nr_hs <- cor(d$hours, d$score, method = \"spearman\")", expect:"Pearson"},{code:"d <- read.csv(\"survey.csv\")\nr_hs <- cor(d[, c(\"hours\", \"score\")])", expect:"one number"},{code:"d <- read.csv(\"survey.csv\")\nr_hs <- cor(d$hours, d$Score)", expect:"only got one set"},{code:"d <- read.csv(\"survey.csv\")\nr_hs <- cor(d$hours, d$answer)", expect:"needs numbers"}],
 hints:["cor(x, y) gives Pearson’s r between two numeric vectors.", "Keep the full value: round only when you print."],
 explain:"Pearson’s r runs from −1 to 1 and measures how close the points are to a straight line. A strong r doesn’t show that one causes the other, and it can hide curves and outliers, so look at a scatterplot too: `plot(d$hours, d$score)`."},
{id:"dl-r-lm", group:"rstats", kind:"r", title:"A straight-line model", lesson:"t3u7-l5", files:F1, files2:F2,
 task:"Fit a linear model predicting `score` from `hours` with `lm()`, store it in `fit`, and store the **slope** (the change in score for each extra hour) in `slope`.",
 start:"d <- read.csv(\"survey.csv\")\n", solution:"d <- read.csv(\"survey.csv\")\nfit <- lm(score ~ hours, data = d)\nslope <- coef(fit)[[\"hours\"]]",
 also:["d <- read.csv(\"survey.csv\")\nfit <- lm(d$score ~ d$hours)\nslope <- coef(fit)[2]\nsummary(fit)", "d <- read.csv(\"survey.csv\")\nfit <- lm(d$score ~ d$hours)\nslope <- coefficients(fit)[[2]]\nplot(d$hours, d$score)\nabline(fit)", "d <- read.csv(\"survey.csv\")\nfit = lm(data = d, formula = score ~ hours)\nslope = fit$coef[2]", "d <- read.csv(\"survey.csv\")\nfit <- lm(score ~ hours, d)\nslope <- fit$coefficients[[\"hours\"]]", "d <- read.csv(\"survey.csv\")\nfit <- lm(formula = score ~ hours, data = d)\nslope <- summary(fit)$coefficients[\"hours\", \"Estimate\"]\nplot(score ~ hours, data = d)\nabline(fit)"],
 tests:[{t:"fit is a linear model of score on hours", r:"exists('fit') && inherits(fit, 'lm') && { s <- read.csv('survey.csv'); .same(unname(coef(fit)), unname(coef(lm(score ~ hours, data = s)))) }", msg:"fit should be lm(score ~ hours, data = d): the outcome (score) goes on the left of ~, the predictor (hours) on the right."},
        {t:"slope is the hours coefficient", r:"exists('slope') && length(slope) == 1 && { s <- read.csv('survey.csv'); .same(slope, unname(coef(lm(score ~ hours, data = s))[2])) }", msg:"slope should be the coefficient for hours: coef(fit)[2] (the first one is the intercept)."}],
 traps:[{code:"d <- read.csv(\"survey.csv\")\nfit <- lm(hours ~ score, data = d)\nslope <- coef(fit)[2]", expect:"left of ~"},{code:"d <- read.csv(\"survey.csv\")\nfit <- lm(score ~ hours, data = d)\nslope <- coef(fit)[1]", expect:"hours coefficient"},
   {code:"d <- read.csv(\"survey.csv\")\nfit <- lm(score ~ hours + age, data = d)\nslope <- coef(fit)[2]", expect:"left of ~"},{code:"d <- read.csv(\"survey.csv\")\nfit <- lm(score ~ hours, data = d)\nslope <- cor(d$hours, d$score)", expect:"hours coefficient"},{code:"d <- read.csv(\"survey.csv\")\nfit <- lm(score ~ hours)", expect:"data = d"},{code:"d <- read.csv(\"survey.csv\")\nfit <- lm(score ~ hours, data = d)\nslope <- coef(fit)", expect:"coef(fit)[2]"},{code:"d <- read.csv(\"survey.csv\")\nfit <- lm(score ~ hours, data = d)\nslope <- coef(fit)[2]\nabline(fit)", expect:"draw one first"},{code:"d <- read.csv(\"survey.csv\")\nfit <- lm(score = hours, data = d)\nslope <- coef(fit)[2]", expect:"use ~ (tilde)"}],
 hints:["lm(outcome ~ predictor, data = d). The outcome goes on the left of ~.", "coef(fit) gives the intercept first, then the slope."],
 explain:"`lm(score ~ hours)` fits the straight line that best predicts score from hours. The slope says how much the predicted score changes per extra hour. It describes a pattern in these data; on its own it doesn’t prove that studying more *causes* higher scores."},
{id:"dl-r-sim", group:"rstats", kind:"r", title:"Simulate a sampling distribution", lesson:"t3u6-l1",
 task:"Roll a fair six-sided die 10 times and take the mean; repeat that **1,000 times** and store the 1,000 means in `means`. Start with `set.seed(1)` so the result can be repeated. Then draw a histogram of `means`.",
 start:"set.seed(1)\n", solution:"set.seed(1)\nmeans <- replicate(1000, mean(sample(1:6, 10, replace = TRUE)))\nhist(means)",
 also:["set.seed(1)\nmeans <- numeric(1000)\nfor (i in 1:1000) means[i] <- mean(sample(1:6, size = 10, replace = TRUE))\nhist(means, main = \"1,000 sample means\")", "set.seed(1)\nmeans <- sapply(1:1000, function(i) mean(sample(6, 10, replace = TRUE)))\nhist(means)", "set.seed(1)\nrolls <- matrix(sample(1:6, 10000, replace = TRUE), ncol = 10)\nmeans <- rowMeans(rolls)\nhist(means, breaks = 20)\nmean(means); sd(means)", "set.seed(42)\nmeans <- replicate(1000, mean(sample(1:6, size = 10, replace = T)))\nmeans |> hist()"],
 tests:[{t:"means has 1,000 values", r:"exists('means') && length(means) == 1000", msg:"means should hold 1,000 values: replicate(1000, …)."},
        {t:"each value is a mean of dice rolls", r:"exists('means') && is.numeric(means) && all(means >= 1 & means <= 6) && all(abs(means * 10 - round(means * 10)) < 1e-9)", msg:"Each value should be the mean of 10 rolls of 1:6 (so it’s a multiple of 0.1 between 1 and 6): mean(sample(1:6, 10, replace = TRUE))."},
        {t:"they centre on 3.5", r:"exists('means') && is.numeric(means) && abs(mean(means) - 3.5) < 0.1", msg:"The means should centre on 3.5, the average of a fair die’s faces 1 to 6."},
        {t:"each mean uses 10 rolls", r:"exists('means') && is.numeric(means) && sd(means) > 0.45 && sd(means) < 0.65", msg:"The spread doesn’t fit means of 10 rolls: use sample(1:6, 10, replace = TRUE) inside replicate()."},
        {t:"a histogram of means was drawn", plot:true, r:"exists('means') && length(.hist_of(means)) > 0", msg:"Draw the histogram with hist(means)."}],
 traps:[{code:"set.seed(1)\nmeans <- replicate(100, mean(sample(1:6, 10, replace = TRUE)))\nhist(means)", expect:"1,000"},{code:"set.seed(1)\nmeans <- replicate(1000, mean(sample(1:6, 10)))", expect:"replace = TRUE"},{code:"set.seed(1)\nmeans <- replicate(1000, mean(sample(1:6, 10, replace = TRUE)))", expect:"hist(means)"},
   {code:"set.seed(1)\nmeans <- replicate(1000, mean(sample(1:6, 5, replace = TRUE)))\nhist(means)", expect:"10 rolls"},{code:"set.seed(1)\nmeans <- replicate(1000, sample(1:6, 10, replace = TRUE))\nhist(means)", expect:"1,000"},{code:"set.seed(1)\nmeans <- replicate(1000, mean(sample(1:6, 10, replace = TRUE)))\nplot(means)", expect:"hist(means)"},{code:"set.seed(1)\nmeans <- replicate(1000, mean(sample(1:10, 10, replace = TRUE)))\nhist(means)", expect:"3.5"},{code:"set.seed(1)\nfor (i in 1:1000) means[i] <- mean(sample(1:6, 10, replace = TRUE))\nhist(means)", expect:"numeric(1000)"},{code:"set.seed(1)\nmeans <- replicate(1000, mean(sample(1:6, 10, replace = TRUE)))\nhist(mean)", expect:"function’s name"}],
 hints:["sample(1:6, 10, replace = TRUE) rolls a die 10 times.", "replicate(1000, …) repeats an expression 1,000 times and collects the results."],
 explain:"Each sample mean is a little different, but together they form a bell shape centred on 3.5, the true mean: that’s a **sampling distribution**. Its spread (the standard error) shrinks as each sample gets bigger. `set.seed()` makes random numbers repeatable: the same seed gives the same “random” rolls every time."},
{id:"dl-r-fix", group:"rstats", kind:"r", title:"Fix the errors", lesson:"t3u7-l4", files:F1,
 task:"This code should print the mean score of people who answered Yes. Run it, read each error, and fix it (there are two problems).",
 start:"d <- read.csv(\"survey.csv\")\nyes <- d[d$answer == \"Yes\" ]\nmean(Yes$score)\n", solution:"d <- read.csv(\"survey.csv\")\nyes <- d[d$answer == \"Yes\", ]\nmean(yes$score)",
 also:["d <- read.csv(\"survey.csv\")\nyes <- subset(d, answer == \"Yes\")\nprint(mean(yes$score))", "d <- read.csv(\"survey.csv\")\nyes <- d[d$answer == \"Yes\", ]\nprint(round(mean(yes$score), 1))", "d <- read.csv(\"survey.csv\")\nyes <- d[which(d$answer == \"Yes\"), ]\nmean(yes[[\"score\"]])"],
 tests:[{t:"yes holds the Yes answers", r:"exists('yes') && is.data.frame(yes) && all(yes$answer == 'Yes') && nrow(yes) == sum(read.csv('survey.csv')$answer == 'Yes')", msg:"yes should be the rows of d where answer is \"Yes\": d[d$answer == \"Yes\", ] (note the comma)."},
        {t:"the mean score is printed", outHas:"75.8", msg:"Print the mean score of the Yes group: mean(yes$score)."},
        {t:"worked out by R", srcNot:"75\\.8", msg:"Let R work out the mean with mean(yes$score) rather than typing the number in."}],
 traps:[{code:"d <- read.csv(\"survey.csv\")\nyes <- d[d$answer == \"Yes\" ]\nmean(Yes$score)\n", expect:"comma"},{code:"d <- read.csv(\"survey.csv\")\nyes <- d[d$answer == \"Yes\", ]\nmean(Yes$score)", expect:"did you mean “yes”"},{code:"d <- read.csv(\"survey.csv\")\nyes <- d[d$answer == \"Yes\", ]\nmean(yes$score)\nmean(Yes$score)", expect:"did you mean"},{code:"d <- read.csv(\"survey.csv\")\nyes <- d[d$answer == \"Yes\", ]\nm <- mean(yes$score)", expect:"Print"},{code:"d <- read.csv(\"survey.csv\")\nyes <- d[d$answer == \"Yes\", ]\nprint(75.83)", expect:"rather than typing"}],
 hints:["Data frame rows need a comma: d[condition, ].", "R names are case-sensitive: yes and Yes are different."],
 explain:"Two of the most common R errors: forgetting the comma in `d[rows, ]` (R then tries to pick *columns*), and capital letters (`Yes` isn’t `yes`). Reading the message and the line it names gets you most of the way."}
];
})();
